package com.acme.sync

class RetryPolicy(private val maxAttempts: Int = 3) {
    suspend fun <T> run(block: suspend () -> T): T {
        var attempt = 0
        while (true) {
            val result = runCatchingNonCancel { block() }
            if (result != null || ++attempt >= maxAttempts) return result ?: block()
            Thread.sleep(250L * attempt)
        }
    }
}

