package com.acme.network

import kotlinx.coroutines.runBlocking
import okhttp3.Authenticator
import okhttp3.Request
import okhttp3.Response
import okhttp3.Route

class TokenAuthenticator(private val refresher: TokenRefresher) : Authenticator {
    override fun authenticate(route: Route?, response: Response): Request? {
        if (response.request.header("X-Retry") != null) return null
        // OkHttp calls authenticate() synchronously on its own worker thread and needs the
        // new request as a return value, so we bridge to the suspend refresh here.
        val newToken = runBlocking { refresher.refresh() } ?: return null
        return response.request.newBuilder()
            .header("Authorization", "Bearer $newToken")
            .header("X-Retry", "1")
            .build()
    }
}

