@Composable
fun CatalogScreen(viewModel: CatalogViewModel, onProductClick: (String) -> Unit, modifier: Modifier = Modifier) {
    val state by viewModel.uiState.collectAsStateWithLifecycle()
    when (val s = state) {
        CatalogUiState.Loading -> CircularProgressIndicator(modifier)
        is CatalogUiState.Loaded -> LazyColumn(modifier) {
            items(s.products, key = { it.id }) { p ->
                ListItem(
                    headlineContent = { Text(p.name) },
                    supportingContent = { Text(p.price.format()) },
                    modifier = Modifier.clickable { onProductClick(p.id) },
                )
            }
        }
    }
}

